INSERT IGNORE INTO diseases (name, alias, icd_code, cause, symptoms, diagnosis, treatment, prevention, classification, body_system, severity, is_infectious, is_chronic, status) VALUES
('普通感冒', '上呼吸道感染', 'CA00', '主要由鼻病毒、冠状病毒等引起，通过飞沫或接触传播', '鼻塞、流涕、打喷嚏、咽喉痛、咳嗽、轻微发热、头痛', '根据临床症状诊断，一般无需特殊检查', '休息、多饮水、对症治疗如解热镇痛药', '勤洗手、避免接触患者、增强免疫力', '呼吸系统疾病', 'RESPIRATORY', 'MILD', 1, 0, 'APPROVED'),
('流行性感冒', '流感', '1E30', '流感病毒感染，分为甲型、乙型和丙型流感病毒', '高热（39-40℃）、咳嗽、咽痛、全身肌肉酸痛、乏力、头痛', '临床症状结合流行病学史、流感病毒抗原检测', '抗病毒治疗（奥司他韦）、对症解热、充分休息', '接种流感疫苗、注意个人卫生、避免去人群密集场所', '呼吸系统疾病', 'RESPIRATORY', 'MODERATE', 1, 0, 'APPROVED'),
('支气管哮喘', '哮喘', 'CA23', '遗传与环境因素共同作用，过敏原、感染、运动等可诱发', '反复发作性喘息、呼吸困难、胸闷、夜间及凌晨加重、咳嗽', '肺功能检查、支气管激发试验、过敏原检测', '吸入糖皮质激素（布地奈德）、支气管扩张剂（沙丁胺醇）', '避免过敏原、规律运动、遵医嘱用药', '呼吸系统疾病', 'RESPIRATORY', 'MODERATE', 0, 1, 'APPROVED'),
('肺炎', '社区获得性肺炎', 'CA40', '细菌（肺炎链球菌）、病毒、支原体等感染肺泡组织', '发热、咳嗽（咳痰）、呼吸困难、胸痛、乏力、食欲不振', '胸部X线、CT检查、血常规、痰培养、炎症标志物检测', '抗生素治疗（阿莫西林、阿奇霉素）、对症支持治疗', '接种肺炎疫苗、增强体质、戒烟', '呼吸系统疾病', 'RESPIRATORY', 'SEVERE', 1, 0, 'APPROVED'),
INSERT IGNORE INTO drugs (name, generic_name, brand_name, efficacy, `usage`, dosage, side_effect, contraindication, drug_type, form, specification, storage, manufacturer, status) VALUES
('氨氯地平', '苯磺酸氨氯地平', '络活喜', '治疗原发性高血压，可单独或联合其他降压药使用。治疗慢性稳定性心绞痛及变异型心绞痛。', '每日一次，晨起服用，不受进餐影响。', '初始剂量5mg/日，最大剂量10mg/日。', '头痛、头晕、下肢水肿、面部潮红、心悸', '对二氢吡啶类过敏者禁用。严重低血压、心源性休克患者禁用。', 'PRESCRIPTION', '片剂', '5mg/片', '密封、阴凉干燥处保存', '辉瑞制药', 'APPROVED'),
('奥美拉唑', '奥美拉唑', '洛赛克', '治疗胃十二指肠溃疡、胃食管反流病、卓-艾综合征', '每日早餐前30分钟服用。', '20mg每日1-2次。十二指肠溃疡疗程4周，胃溃疡疗程6-8周。', '头痛、腹泻、便秘、恶心、皮疹', '对本品过敏者禁用。严重肝功能不全者慎用。', 'PRESCRIPTION', '胶囊', '20mg/粒', '避光、密封、阴凉干燥处保存', '阿斯利康', 'APPROVED'),
('阿莫西林', '阿莫西林', '阿莫仙', '治疗敏感菌引起的呼吸道感染、泌尿生殖道感染、皮肤软组织感染', '口服，不受进食影响。', '成人0.5g/次，每6-8小时一次。儿童25-50mg/kg/日。', '皮疹、腹泻、恶心、药物热。偶见过敏性休克。', '青霉素过敏者禁用。传染性单核细胞增多症患者禁用。', 'PRESCRIPTION', '胶囊', '0.5g/粒', '密封、阴凉干燥处保存', '华北制药', 'APPROVED'),
('布洛芬', '布洛芬', '芬必得', '缓解各种轻度至中度疼痛。退热。治疗类风湿关节炎及骨关节炎。', '餐后服用以减少胃肠道刺激。', '止痛/退热：0.2-0.4g/次，每4-6小时一次。关节炎：0.4-0.6g/次，每日3-4次。', '胃肠道不适、胃溃疡、出血、肾功能损害、头痛', '消化性溃疡患者禁用。严重心肾功能不全者、孕妇及哺乳期妇女禁用。', 'OTC', '缓释胶囊', '0.3g/粒', '密封、阴凉干燥处保存', '中美史克', 'APPROVED'),
('对乙酰氨基酚', '对乙酰氨基酚', '泰诺林', '普通感冒或流感引起的发热。轻至中度疼痛：头痛、关节痛、牙痛、肌肉痛。', '口服，退热不超过3天，镇痛不超过5天。', '成人0.5g/次，每4-6小时一次。最大日剂量2g。儿童10-15mg/kg/次。', '恶心、呕吐。超剂量使用可致严重肝毒性。', '严重肝肾功能不全者禁用。对本品过敏者禁用。', 'OTC', '片剂', '0.5g/片', '密封、阴凉干燥处保存', '强生', 'APPROVED'),
('二甲双胍', '盐酸二甲双胍', '格华止', '2型糖尿病的一线药物，尤其适用于超重和肥胖的2型糖尿病患者。', '随餐或餐后服用以减轻胃肠道反应。', '起始剂量500mg每日2-3次，最大剂量2000mg/日。', '恶心、腹泻、食欲减退。偶见乳酸酸中毒。', '肾功能不全（eGFR<30ml/min）禁用。严重肝功能不全禁用。', 'PRESCRIPTION', '片剂', '500mg/片', '密封、阴凉干燥处保存', '默克', 'APPROVED'),
('阿司匹林', '阿司匹林', '拜阿司匹林', '心血管疾病一级/二级预防（抗血小板聚集）。解热镇痛（大剂量）。', '餐后整片吞服，不可嚼碎。', '预防心脑血管疾病：75-100mg/日。解热镇痛：0.3-0.6g/次。', '胃肠道不适、出血风险增加、过敏反应', '消化性溃疡、出血性疾病、严重肝肾功能不全者禁用。儿童病毒感染期间禁用。', 'OTC', '肠溶片', '100mg/片', '密封、阴凉干燥处保存', '拜耳', 'APPROVED'),
('缬沙坦', '缬沙坦', '代文', '治疗原发性高血压。治疗心力衰竭（NYHA II-IV级）。降低心肌梗死后心血管死亡率。', '每日一次，不受进食影响。', '起始剂量80mg/日，可根据血压调整至320mg/日。', '头晕、乏力、高钾血症', '双侧肾动脉狭窄、妊娠、对本品过敏者禁用。', 'PRESCRIPTION', '胶囊', '80mg/粒', '密封、阴凉干燥处保存', '诺华', 'APPROVED'),
('奥司他韦', '磷酸奥司他韦', '达菲', '治疗及预防甲型和乙型流感。', '症状出现48小时内开始服用。', '治疗：75mg每日2次，疗程5天。预防：75mg每日1次。', '恶心、呕吐、头痛', '对本品过敏者禁用。严重肾功能不全需调整剂量。', 'PRESCRIPTION', '胶囊', '75mg/粒', '密封、阴凉干燥处保存', '罗氏', 'APPROVED'),
('硝苯地平', '硝苯地平控释片', '拜新同', '治疗原发性高血压。治疗慢性稳定性心绞痛。', '每日一次，不可掰开或嚼碎服用。', '初始剂量30mg/日，最大剂量60mg/日。', '头痛、下肢水肿、面部潮红、心悸', '心源性休克、不稳定性心绞痛、急性心肌梗死禁用。', 'PRESCRIPTION', '控释片', '30mg/片', '避光、密封、阴凉处保存', '拜耳', 'APPROVED');
INSERT IGNORE INTO skills (name, category, description, content, is_active, priority, version) VALUES
('症状分析', 'DIAGNOSIS', '根据患者描述的症状进行系统性分析，识别可能的疾病', '你是一名经验丰富的临床医生。请根据患者描述的症状进行系统性分析：\n1. 分析症状特征（起病时间、严重程度、诱发和缓解因素）\n2. 列出可能的鉴别诊断\n3. 建议必要的检查项目\n4. 提供暂行处理建议', 1, 100, '1.0'),
('用药指导', 'MEDICATION', '为患者提供药物使用指导，包括用法用量、注意事项和不良反应', '你是一名临床药师。请为患者提供专业的用药指导：\n1. 说明药物的正确用法用量\n2. 提醒重要的注意事项和禁忌\n3. 告知可能的不良反应及应对方法\n4. 强调遵医嘱用药的重要性', 1, 90, '1.0'),
('健康教育', 'EDUCATION', '为患者提供疾病相关的健康教育，包括生活方式指导和预防措施', '你是一名健康教育专家。请为患者提供针对性的健康教育：\n1. 解释疾病的本质和发展过程\n2. 提供饮食和运动建议\n3. 强调生活方式改变的重要性\n4. 制定个性化的健康管理计划', 1, 80, '1.0'),
('中医调理', 'TCM', '结合中医理论为患者提供中药调理和养生建议', '你是一名中西医结合专家。请结合中医理论提供调理建议：\n1. 从中医角度分析体质和病因\n2. 推荐适合的中成药或方剂\n3. 提供针灸、推拿等辅助治疗建议\n4. 结合现代医学知识综合判断', 1, 70, '1.0'),
('儿科咨询', 'PEDIATRICS', '专门针对儿童常见疾病的咨询和用药指导', '你是一名儿科医生。请注意儿童用药的特殊性：\n1. 根据年龄和体重调整用药剂量\n2. 推荐适合儿童的药物剂型\n3. 提醒家长注意观察儿童用药后反应\n4. 提供儿童护理和营养建议', 1, 60, '1.0');
